def emi(principal: float, monthly_rate: float, months: int) -> float:
    if months <= 0:
        raise ValueError('months must be positive')
    if monthly_rate == 0:
        return principal / months
    factor = (1 + monthly_rate) ** months
    return principal * monthly_rate * factor / (factor - 1)
